INSERT INTO skills (code, subject_code, name) VALUES
    ('MULT_FACTS_G3', 'MATH', 'Multiplication Facts to 10'),
    ('HOMOPHONES', 'ENGLISH', 'Homophones');
INSERT INTO lessons (id, code, subject_code, grade_level, display_order, title, description) VALUES
    ('14000000-0000-0000-0000-000000000018', 'G3-MULTFACT-01', 'MATH', 'GRADE_3', 10, 'Multiplication Facts: 6s to 9s', 'Practice the harder times-table facts with tricks that help.'),
    ('14000000-0000-0000-0000-000000000019', 'G3-ENG-HOMOPHONE-01', 'ENGLISH', 'GRADE_3', 9, 'Homophones', 'Words that sound the same but have different spellings and meanings.');
INSERT INTO exercises (id, lesson_code, skill_code, display_order, prompt, answer_index, explanation, hint) VALUES
    ('34000000-0000-0000-0000-000000000001', 'G3-MULT-01', 'MULT_BASIC', 4, 'What is 4 x 5?', 0, '4 x 5 = 20. That''s 4 groups of 5: 5, 10, 15, 20.', 'Skip count by 5 four times.'),
    ('34000000-0000-0000-0000-000000000002', 'G3-MULT-01', 'MULT_BASIC', 5, 'What is 2 x 9?', 1, '2 x 9 = 18. Doubling 9 gives 18.', 'Times 2 means double.'),
    ('34000000-0000-0000-0000-000000000003', 'G3-MULT-01', 'MULT_BASIC', 6, 'What is 7 x 1?', 1, 'Any number times 1 stays the same: 7 x 1 = 7.', 'One group of 7.'),
    ('34000000-0000-0000-0000-000000000004', 'G3-DIV-01', 'DIV_BASIC', 4, 'What is 15 / 5?', 2, '15 / 5 = 3, because 5 x 3 = 15.', 'How many 5s make 15?'),
    ('34000000-0000-0000-0000-000000000005', 'G3-DIV-01', 'DIV_BASIC', 5, 'What is 28 / 7?', 0, '28 / 7 = 4, because 7 x 4 = 28.', 'Think: 7 times what is 28?'),
    ('34000000-0000-0000-0000-000000000006', 'G3-DIV-01', 'DIV_BASIC', 6, 'What is 9 / 9?', 2, 'Any number divided by itself is 1.', 'How many 9s fit in 9?'),
    ('34000000-0000-0000-0000-000000000007', 'G3-FRAC-01', 'FRACTIONS_INTRO', 4, 'A sandwich is cut into 2 equal parts. What is each part called?', 2, 'Two equal parts are halves, so each is 1/2.', 'Two equal parts.'),
    ('34000000-0000-0000-0000-000000000008', 'G3-FRAC-01', 'FRACTIONS_INTRO', 5, '3 out of 4 equal parts of a shape are shaded. What fraction is shaded?', 0, '3 shaded out of 4 parts is 3/4.', 'Shaded parts go on top.'),
    ('34000000-0000-0000-0000-000000000009', 'G3-FRAC-01', 'FRACTIONS_INTRO', 6, 'How many fourths make one whole?', 1, '4 fourths = 4/4 = 1 whole.', 'Count the slices of a pizza cut in 4.'),
    ('34000000-0000-0000-0000-000000000010', 'G3-AREA-01', 'AREA_PERIMETER', 4, 'A square has sides of 3 units. What is its area?', 2, 'Area = 3 x 3 = 9 square units.', 'Multiply side by side.'),
    ('34000000-0000-0000-0000-000000000011', 'G3-AREA-01', 'AREA_PERIMETER', 5, 'A rectangle is 5 units long and 2 units wide. What is its area?', 2, 'Area = 5 x 2 = 10.', 'Multiply length by width.'),
    ('34000000-0000-0000-0000-000000000012', 'G3-AREA-01', 'AREA_PERIMETER', 6, 'What does perimeter measure?', 2, 'Perimeter is the total length around the outside.', 'Think of walking around a fence.'),
    ('34000000-0000-0000-0000-000000000013', 'G3-ROUND-01', 'ROUNDING', 4, 'Round 64 to the nearest ten.', 0, '64 is closer to 60 than to 70.', 'Look at the ones digit: 4 is less than 5.'),
    ('34000000-0000-0000-0000-000000000014', 'G3-ROUND-01', 'ROUNDING', 5, 'Round 349 to the nearest hundred.', 0, '349 is closer to 300. Look at the tens: 4 is less than 5.', 'Look at the tens digit.'),
    ('34000000-0000-0000-0000-000000000015', 'G3-ROUND-01', 'ROUNDING', 6, 'Round 75 to the nearest ten.', 0, 'When the ones digit is 5, round up: 80.', '5 or more rounds up.'),
    ('34000000-0000-0000-0000-000000000016', 'G3-TIME-01', 'TIME_MINUTE', 4, 'The long hand points to the 4. How many minutes past the hour is it?', 1, 'Each number is 5 minutes: 4 x 5 = 20.', 'Count by 5s to the 4.'),
    ('34000000-0000-0000-0000-000000000017', 'G3-TIME-01', 'TIME_MINUTE', 5, 'The long hand points to the 11. How many minutes past the hour is it?', 0, '11 x 5 = 55 minutes.', 'Count by 5s to the 11.'),
    ('34000000-0000-0000-0000-000000000018', 'G3-TIME-01', 'TIME_MINUTE', 6, 'How many minutes are in one hour?', 0, 'One hour = 60 minutes.', 'The long hand goes all the way around once.'),
    ('34000000-0000-0000-0000-000000000019', 'G3-GRAPH-01', 'BAR_GRAPHS', 4, 'A graph shows Cats: 6, Dogs: 9, Fish: 3. How many more dogs than cats?', 2, '9 - 6 = 3 more dogs.', 'Subtract the smaller number.'),
    ('34000000-0000-0000-0000-000000000020', 'G3-GRAPH-01', 'BAR_GRAPHS', 5, 'A graph shows Apples: 4, Bananas: 5, Pears: 1. How many fruits in all?', 1, '4 + 5 + 1 = 10.', 'Add all the bars.'),
    ('34000000-0000-0000-0000-000000000021', 'G3-GRAPH-01', 'BAR_GRAPHS', 6, 'On a bar graph, what does the tallest bar show?', 2, 'The tallest bar reaches the highest number.', 'Taller means more.'),
    ('34000000-0000-0000-0000-000000000022', 'G3-MULTIDIGIT-01', 'MULTIDIGIT_ADDSUB', 4, 'What is 418 + 263?', 1, '8 + 3 = 11 (carry 1), 1 + 6 + 1 = 8, 4 + 2 = 6: 681.', 'Regroup the ones.'),
    ('34000000-0000-0000-0000-000000000023', 'G3-MULTIDIGIT-01', 'MULTIDIGIT_ADDSUB', 5, 'What is 702 - 315?', 0, 'Regroup across the zero: 702 - 315 = 387.', 'Borrow from the hundreds.'),
    ('34000000-0000-0000-0000-000000000024', 'G3-MULTIDIGIT-01', 'MULTIDIGIT_ADDSUB', 6, 'What is 999 - 111?', 2, 'Each digit: 9 - 1 = 8, so 888.', 'Subtract each place.'),
    ('34000000-0000-0000-0000-000000000025', 'G3-WORD-01', 'WORD_PROB_G3', 4, 'There are 8 tables with 4 chairs each. How many chairs in all?', 2, '8 x 4 = 32.', 'Equal groups means multiply.'),
    ('34000000-0000-0000-0000-000000000026', 'G3-WORD-01', 'WORD_PROB_G3', 5, '45 stickers are shared equally among 5 kids. How many does each get?', 0, '45 / 5 = 9.', 'Shared equally means divide.'),
    ('34000000-0000-0000-0000-000000000027', 'G3-WORD-01', 'WORD_PROB_G3', 6, 'A pack has 6 juice boxes. How many packs do you need for 30 kids?', 2, '30 / 6 = 5 packs.', 'How many 6s make 30?'),
    ('34000000-0000-0000-0000-000000000028', 'G3-ENG-COMP-01', 'COMPREHENSION_G3', 4, 'Read: "Rosa saved her allowance for months. Finally, she bought the bike she wanted." Why could Rosa buy the bike?', 0, 'She saved her allowance until she had enough.', 'What did Rosa do for months?'),
    ('34000000-0000-0000-0000-000000000029', 'G3-ENG-COMP-01', 'COMPREHENSION_G3', 5, 'Read: "The baby yawned and rubbed her eyes." How does the baby feel?', 2, 'Yawning and rubbing eyes are signs of being tired.', 'When do you yawn?'),
    ('34000000-0000-0000-0000-000000000030', 'G3-ENG-COMP-01', 'COMPREHENSION_G3', 6, 'Read: "Leaves turned orange and fell. Kids jumped in the piles." What season is it?', 1, 'Orange leaves falling happen in fall (autumn).', 'When do leaves fall from trees?'),
    ('34000000-0000-0000-0000-000000000031', 'G3-ENG-CONTEXT-01', 'CONTEXT_CLUES', 4, '"The puppy was so timid that it hid behind its mom." What does "timid" mean?', 1, 'Hiding shows the puppy was shy.', 'What would make a puppy hide?'),
    ('34000000-0000-0000-0000-000000000032', 'G3-ENG-CONTEXT-01', 'CONTEXT_CLUES', 5, '"The soup was scalding, so I waited for it to cool." What does "scalding" mean?', 1, 'Waiting for it to cool means it was very hot.', 'Why would you wait for soup to cool?'),
    ('34000000-0000-0000-0000-000000000033', 'G3-ENG-CONTEXT-01', 'CONTEXT_CLUES', 6, '"After the long hike, we were famished and ate everything." What does "famished" mean?', 0, 'Eating everything shows they were very hungry.', 'What did they do next?'),
    ('34000000-0000-0000-0000-000000000034', 'G3-ENG-PREFIX-01', 'PREFIX_SUFFIX', 4, 'What does the prefix "pre-" mean in "preview"?', 1, 'Pre- means before: a preview is seen before.', 'Think of "preschool".'),
    ('34000000-0000-0000-0000-000000000035', 'G3-ENG-PREFIX-01', 'PREFIX_SUFFIX', 5, 'What does the suffix "-less" mean in "fearless"?', 2, '-less means without: fearless = without fear.', 'The opposite of -ful.'),
    ('34000000-0000-0000-0000-000000000036', 'G3-ENG-PREFIX-01', 'PREFIX_SUFFIX', 6, 'What does "misspell" mean?', 1, 'Mis- means wrongly.', 'Think of "mistake".'),
    ('34000000-0000-0000-0000-000000000037', 'G3-ENG-POS-01', 'PARTS_OF_SPEECH_G3', 4, 'In "The turtle walked slowly," which word is the adverb?', 0, '"slowly" tells how the turtle walked.', 'Many adverbs end in -ly.'),
    ('34000000-0000-0000-0000-000000000038', 'G3-ENG-POS-01', 'PARTS_OF_SPEECH_G3', 5, 'Which word is an adverb?', 0, '"happily" describes how something is done.', 'Look for -ly.'),
    ('34000000-0000-0000-0000-000000000039', 'G3-ENG-POS-01', 'PARTS_OF_SPEECH_G3', 6, 'In "We will play outside tomorrow," which word tells when?', 0, '"tomorrow" is an adverb telling when.', 'Which word is about time?'),
    ('34000000-0000-0000-0000-000000000040', 'G3-ENG-COMPARE-01', 'COMPARE_CONTRAST', 4, 'Frogs live on land and in water; fish live only in water. What is one difference?', 0, 'Only frogs can also live on land.', 'Look for what is not the same.'),
    ('34000000-0000-0000-0000-000000000041', 'G3-ENG-COMPARE-01', 'COMPARE_CONTRAST', 5, 'Apples and oranges are both fruits. Which word signals they are alike?', 2, '"Both" shows something they share.', 'Which word means the two are alike?'),
    ('34000000-0000-0000-0000-000000000042', 'G3-ENG-COMPARE-01', 'COMPARE_CONTRAST', 6, 'Which word often signals a difference?', 1, '"However" introduces a contrast.', 'Which word means "but"?'),
    ('34000000-0000-0000-0000-000000000043', 'G3-ENG-CAUSE-01', 'CAUSE_EFFECT', 4, 'Sam studied hard, so he passed his test. What was the cause?', 0, 'Studying hard caused him to pass.', 'The cause comes before "so".'),
    ('34000000-0000-0000-0000-000000000044', 'G3-ENG-CAUSE-01', 'CAUSE_EFFECT', 5, 'The plant died because nobody watered it. What was the effect?', 1, 'The effect is what happened: the plant died.', 'The effect is the result.'),
    ('34000000-0000-0000-0000-000000000045', 'G3-ENG-CAUSE-01', 'CAUSE_EFFECT', 6, 'Which word often signals a cause?', 0, '"Because" introduces a reason.', 'Which word gives a reason?'),
    ('34000000-0000-0000-0000-000000000046', 'G3-ENG-FACTOP-01', 'FACT_OPINION', 4, 'Which sentence tells how someone feels, not a fact?', 2, '"Best" is a feeling, not something you can prove.', 'Look for feeling words like best.'),
    ('34000000-0000-0000-0000-000000000047', 'G3-ENG-FACTOP-01', 'FACT_OPINION', 5, 'Which sentence can be checked and proven?', 0, 'You can check that a week has seven days.', 'Can you prove it?'),
    ('34000000-0000-0000-0000-000000000048', 'G3-ENG-FACTOP-01', 'FACT_OPINION', 6, 'Which word often signals an opinion?', 2, '"Delicious" is a personal judgment.', 'Which word is a feeling?'),
    ('34000000-0000-0000-0000-000000000049', 'G3-ENG-SVA-01', 'SUBJECT_VERB', 4, 'Which sentence has the subject and verb matching?', 2, 'Plural "birds" goes with "sing".', 'More than one subject: no -s on the verb.'),
    ('34000000-0000-0000-0000-000000000050', 'G3-ENG-SVA-01', 'SUBJECT_VERB', 5, 'Which verb fits: "My brother ___ soccer."', 1, 'One brother goes with "plays".', 'One person: add -s.'),
    ('34000000-0000-0000-0000-000000000051', 'G3-ENG-SVA-01', 'SUBJECT_VERB', 6, 'Which verb fits: "Tom and Ana ___ friends."', 1, 'Two people go with "are".', 'Tom and Ana is two people.'),
    ('34000000-0000-0000-0000-000000000052', 'G3-MULTFACT-01', 'MULT_FACTS_G3', 1, 'What is 6 x 7?', 2, '6 x 7 = 42.', '6 x 6 = 36, plus one more 6.'),
    ('34000000-0000-0000-0000-000000000053', 'G3-MULTFACT-01', 'MULT_FACTS_G3', 2, 'What is 8 x 8?', 2, '8 x 8 = 64.', 'Double 8 three times: 16, 32, 64.'),
    ('34000000-0000-0000-0000-000000000054', 'G3-MULTFACT-01', 'MULT_FACTS_G3', 3, 'What is 9 x 6?', 1, '9 x 6 = 54. Trick: 10 x 6 = 60, minus 6 = 54.', 'Do 10 x 6, then take away one 6.'),
    ('34000000-0000-0000-0000-000000000055', 'G3-MULTFACT-01', 'MULT_FACTS_G3', 4, 'What is 7 x 8?', 2, '7 x 8 = 56. Remember 5, 6, 7, 8: 56 = 7 x 8.', 'Think "5, 6, 7, 8".'),
    ('34000000-0000-0000-0000-000000000056', 'G3-MULTFACT-01', 'MULT_FACTS_G3', 5, 'What is 9 x 9?', 0, '9 x 9 = 81.', '10 x 9 = 90, minus 9.'),
    ('34000000-0000-0000-0000-000000000057', 'G3-MULTFACT-01', 'MULT_FACTS_G3', 6, 'What is 6 x 8?', 0, '6 x 8 = 48.', 'Double 3 x 8 = 24.'),
    ('34000000-0000-0000-0000-000000000058', 'G3-ENG-HOMOPHONE-01', 'HOMOPHONES', 1, 'Which word fits: "I can ___ the ocean."', 0, '"See" means to look; "sea" is the ocean.', 'Which one means to look?'),
    ('34000000-0000-0000-0000-000000000059', 'G3-ENG-HOMOPHONE-01', 'HOMOPHONES', 2, 'Which word fits: "We ate ___ pizzas."', 1, '"Two" is the number 2.', 'Which one is a number?'),
    ('34000000-0000-0000-0000-000000000060', 'G3-ENG-HOMOPHONE-01', 'HOMOPHONES', 3, 'Which word fits: "___ dog is very friendly."', 0, '"Their" shows something belongs to them.', 'Whose dog?'),
    ('34000000-0000-0000-0000-000000000061', 'G3-ENG-HOMOPHONE-01', 'HOMOPHONES', 4, 'Which word fits: "The wind ___ the leaves away."', 2, '"Blew" is the past of blow; "blue" is a color.', 'Which one is an action?'),
    ('34000000-0000-0000-0000-000000000062', 'G3-ENG-HOMOPHONE-01', 'HOMOPHONES', 5, 'Which word fits: "I ___ the answer!"', 1, '"Know" means to understand; "no" is the opposite of yes.', 'Which one means to understand?'),
    ('34000000-0000-0000-0000-000000000063', 'G3-ENG-HOMOPHONE-01', 'HOMOPHONES', 6, 'Which pair are homophones?', 0, 'Night and knight sound the same but mean different things.', 'They must sound exactly the same.');
